package dev.doughbay.fabric;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import static dev.doughbay.fabric.AutomaticReportDetector.*;
class AutomaticReportPayloadTest {
 static AutomaticReportMetadata metadata(String build){return AutomaticReportMetadata.of(build,"26.2",new Candidate(Failure.DURABLE_WRITE_REJECTED,Signature.IMMUTABLE_POSITION_IDENTITY_CONFLICT));}
 static BugReportPayload payload(){var a=metadata("0.1.0");return new BugReportPayload("0.1.0","26.2",a.description(),a.expected(),BugReportDiagnostics.counters(""));}
 @Test void anonymousFingerprintIsStableAcrossReportersButChangesByBuild(){assertEquals(metadata("0.1.0"),metadata("0.1.0"));assertNotEquals(metadata("0.1.0").fingerprint(),metadata("0.1.1").fingerprint());}
 @Test void schemaThreeAddsOnlyValidatedGroupingFields()throws Exception{var json=new ObjectMapper().readTree(payload().json("",metadata("0.1.0")));assertEquals(3,json.path("schemaVersion").asInt());assertEquals(7,json.size());assertEquals(3,json.path("automatic").size());assertEquals(metadata("0.1.0").fingerprint(),json.path("automatic").path("fingerprint").asText());}
 @Test void manualSchemasRemainUnchanged()throws Exception{var json=new ObjectMapper();assertEquals(1,json.readTree(payload().json()).path("schemaVersion").asInt());assertEquals(2,json.readTree(payload().json(BugReportLog.sanitize(""))).path("schemaVersion").asInt());}
 @Test void forgedFingerprintOrPrivateAutomaticDescriptionIsRefused(){var bad=new AutomaticReportMetadata(Failure.DURABLE_WRITE_REJECTED,Signature.IMMUTABLE_POSITION_IDENTITY_CONFLICT,"0".repeat(64));assertThrows(IllegalArgumentException.class,()->payload().json("",bad));var p=new BugReportPayload("0.1.0","26.2","PrivatePlayer is having a problem",metadata("0.1.0").expected(),BugReportDiagnostics.counters(""));assertThrows(IllegalArgumentException.class,()->p.json("",metadata("0.1.0")));}
 @Test void existingManualReceiverCannotReceiveAutomaticReports()throws Exception{var caps=new ObjectMapper().readTree("{\"schemaVersions\":[1,2],\"configured\":true,\"requiresAuthentication\":false}");assertThrows(IllegalStateException.class,()->BugReportTransport.automaticRequest(payload(),"retry-key-123","",metadata("0.1.0"),caps));}
 @Test void groupedCapabilitiesPermitOnlyTheAdvertisedKindWithoutAuthorization()throws Exception{var caps=new ObjectMapper().readTree("{\"schemaVersions\":[1,2,3],\"configured\":true,\"requiresAuthentication\":false,\"maxBodyBytes\":32768,\"automaticReports\":{\"supported\":true,\"grouped\":true,\"schemaVersion\":3,\"kinds\":[\"DURABLE_WRITE_REJECTED\"]}}");var req=BugReportTransport.automaticRequest(payload(),"retry-key-123","",metadata("0.1.0"),caps);assertEquals("https://gonuts.at/v1/bugs",req.uri().toString());assertTrue(req.headers().firstValue("Authorization").isEmpty());assertFalse(BugReportTransport.advertisesAutomaticReports(caps,Failure.PERSISTENCE_WRITER_FAILED));}
}
